// ====== MATCHING ENGINE: rule-based scoring ======
const WEIGHTS = { sertifikasi: 30, bahasa: 30, usia: 15, kesehatan: 15, pengalaman: 10 }; // total 100
const THRESHOLDS = [[75, 'Sangat Cocok'], [60, 'Cocok'], [0, 'Kurang Cocok']];
const JLPT = { N5: 1, N4: 2, N3: 3, N2: 4, N1: 5 };
const label = (s) => THRESHOLDS.find(([t]) => s >= t)[1];

const d = $input.first().json;

function score(c, j) {
  const certs = c.sertifikasi ? c.sertifikasi.split(';') : [];
  const lvl = JLPT[c.jlpt] || 0;
  const minLvl = JLPT[j.jlpt_min];
  const gugur = [];

  // --- Lapis 1: syarat mutlak (knock-out) ---
  if (!(c.usia >= j.usia_min && c.usia <= j.usia_max)) gugur.push(`usia ${c.usia} di luar rentang ${j.usia_min}-${j.usia_max}`);
  if (j.gender !== 'any' && c.gender !== j.gender) gugur.push('jenis kelamin tidak sesuai syarat');
  if (j.sertifikasi_wajib === 'ya' && !certs.includes(j.sertifikasi)) gugur.push(`belum memiliki sertifikat wajib ${j.sertifikasi}`);
  if (lvl < minLvl) gugur.push(`JLPT ${c.jlpt} di bawah minimum ${j.jlpt_min}`);
  if (c.kesehatan === 'tidak_fit') gugur.push('hasil kesehatan tidak memenuhi syarat');
  if (gugur.length) return { eligible: false, skor: 0, bd: {}, gugur };

  // --- Lapis 2: skor berbobot ---
  const bd = {};
  bd.sertifikasi = certs.includes(j.sertifikasi) ? WEIGHTS.sertifikasi : (certs.length ? Math.round(WEIGHTS.sertifikasi / 3) : 0);
  const extra = Math.min(lvl - minLvl, 1);
  bd.bahasa = Math.round(WEIGHTS.bahasa * (2 / 3 + extra / 3));
  const ideal = c.usia >= j.usia_ideal_min && c.usia <= j.usia_ideal_max;
  bd.usia = ideal ? WEIGHTS.usia : Math.round(WEIGHTS.usia / 2);
  bd.kesehatan = c.kesehatan === 'sehat' ? WEIGHTS.kesehatan : Math.round(WEIGHTS.kesehatan / 2);
  bd.pengalaman = Math.round(WEIGHTS.pengalaman * Math.min(c.pengalaman_thn, 3) / 3);
  const skor = Object.values(bd).reduce((a, b) => a + b, 0);
  return { eligible: true, skor, bd, gugur: [] };
}

const matches = [];
for (const c of d.candidates) {
  for (const j of d.jobs) {
    const r = score(c, j);
    matches.push({
      kandidat_id: c.id, kandidat: c.nama, lowongan_id: j.id, perusahaan: j.perusahaan,
      eligible: r.eligible ? 'ya' : 'tidak',
      skor: r.skor,
      kategori: r.eligible ? label(r.skor) : 'Tidak Memenuhi Syarat',
      rincian: Object.entries(r.bd).map(([k, v]) => `${k}=${v}`).join('; '),
      catatan: r.gugur.join('; ') + (r.eligible && c.kesehatan === 'perlu_review' ? ' | perlu review manual kesehatan' : ''),
    });
  }
}
return [{ json: { ...d, matches } }];

// ====== TRIGGER REMINDER: cek H-n + cegah kirim ganda ======
const REMINDER_RULES = { interview: [3, 1], medical: [3, 1], dokumen: [7, 3, 1] };
const HARI = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const BULAN = ['', 'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
const tgl = (s) => { const t = new Date(s + 'T00:00:00Z'); return `${HARI[t.getUTCDay()]}, ${t.getUTCDate()} ${BULAN[t.getUTCMonth() + 1]} ${t.getUTCFullYear()}`; };
const diff = (a, b) => Math.round((Date.parse(b) - Date.parse(a)) / 86400000);
const waktu = (n) => (n === 1 ? 'BESOK' : `${n} hari lagi`);

const d = $input.first().json;
const jobsById = Object.fromEntries(d.jobs.map((j) => [j.id, j]));

// Log pengiriman (tersimpan di workflow static data; aktif saat workflow di-Activate)
const sd = $getWorkflowStaticData('global');
sd.sentLog = sd.sentLog || {};

function pesan(c, job, stage, date, n) {
  const nama = c.nama.split(' ')[0];
  const perusahaan = job ? job.perusahaan : 'perusahaan penerima';
  let subject, isi;
  if (stage === 'interview') {
    subject = `[Minori Group] Pengingat Wawancara H-${n}`;
    isi = `Wawancara dengan ${perusahaan} akan dilaksanakan ${waktu(n)}:\n📅 ${tgl(date)}\n🕐 ${c.interview_jam} WIB\n🔗 ${c.interview_link}\n\nPersiapan: pelajari profil perusahaan, latih jikoshoukai (perkenalan diri), pakai pakaian rapi, dan tes koneksi internet 30 menit sebelumnya.`;
  } else if (stage === 'medical') {
    subject = `[Minori Group] Pengingat Medical Check-up H-${n}`;
    isi = `Medical check-up Anda akan dilaksanakan ${waktu(n)}:\n📅 ${tgl(date)}\n📍 ${c.medical_tempat}\n\nPersiapan: puasa 8-10 jam sebelum pemeriksaan, bawa KTP/paspor, dan jangan lupa istirahat cukup malam sebelumnya.`;
  } else {
    subject = `[Minori Group] Tenggat Dokumen H-${n}`;
    isi = `Tenggat pengumpulan dokumen ${waktu(n)}:\n📅 ${tgl(date)}\n📄 Dokumen: ${c.dokumen_nama}\n\nMohon kirim ke tim penempatan sebelum tenggat. Dokumen terlambat dapat menunda jadwal keberangkatan Anda.`;
  }
  const whatsapp = `Halo ${nama} 👋, ini pengingat otomatis dari *Minori Group*.\n\n${isi}\n\nBalas pesan ini bila ada kendala. Semangat! 💪`;
  const email_body = `Yth. ${c.nama},\n\n${isi}\n\nSalam,\nTim Penempatan Minori Group`;
  return { subject, whatsapp, email_body };
}

const reminders = [];
let dilewati = 0;
for (const c of d.candidates) {
  const job = jobsById[c.lowongan_dilamar];
  const tahap = { interview: c.interview_tgl, medical: c.medical_tgl, dokumen: c.dokumen_tenggat };
  for (const [stage, date] of Object.entries(tahap)) {
    if (!date) continue;
    const n = diff(d.today, date);
    if (!REMINDER_RULES[stage].includes(n)) continue;
    const kunci = `${c.id}|${stage}|H-${n}|${date}`;
    if (sd.sentLog[kunci]) { dilewati++; continue; }          // sudah pernah dikirim
    sd.sentLog[kunci] = new Date().toISOString();
    reminders.push({
      kunci, kandidat: c.nama, phone: c.phone, email_to: c.email,
      tahap: stage, offset: `H-${n}`, tanggal_tahap: date, ...pesan(c, job, stage, date, n),
    });
  }
}
return [{ json: { ...d, reminders, dilewati } }];

// ====== LAPORAN MANAJEMEN (Markdown) ======
const HARI = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const BULAN = ['', 'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
const tgl = (s) => { const t = new Date(s + 'T00:00:00Z'); return `${HARI[t.getUTCDay()]}, ${t.getUTCDate()} ${BULAN[t.getUTCMonth() + 1]} ${t.getUTCFullYear()}`; };
const diff = (a, b) => Math.round((Date.parse(b) - Date.parse(a)) / 86400000);

const d = $input.first().json;
const best = (id) => {
  const m = d.matches.filter((r) => r.kandidat_id === id && r.eligible === 'ya');
  return m.length ? m.reduce((a, b) => (b.skor > a.skor ? b : a)) : null;
};

const L = [];
L.push(`# Laporan Progres Penempatan - ${tgl(d.today)}\n`);
L.push('## Ringkasan\n');
L.push(`- Total kandidat aktif: **${d.candidates.length}**`);
L.push(`- Total lowongan terbuka: **${d.jobs.length}**`);
L.push(`- Reminder dibuat hari ini: **${d.reminders.length}**\n`);

L.push('## Kandidat per Tahap\n');
L.push('| Tahap | Jumlah |\n|---|---|');
const perTahap = {};
d.candidates.forEach((c) => { perTahap[c.tahap] = (perTahap[c.tahap] || 0) + 1; });
Object.entries(perTahap).forEach(([t, n]) => L.push(`| ${t} | ${n} |`));

L.push('\n## Rekomendasi Lowongan Terbaik per Kandidat\n');
L.push('| Kandidat | Tahap | Lowongan Terbaik | Skor | Kategori |\n|---|---|---|---|---|');
d.candidates.forEach((c) => {
  const b = best(c.id);
  L.push(b ? `| ${c.nama} | ${c.tahap} | ${b.perusahaan} | ${b.skor} | ${b.kategori} |`
           : `| ${c.nama} | ${c.tahap} | - (belum ada yang memenuhi syarat) | 0 | Perlu pembinaan |`);
});

L.push('\n## Perlu Perhatian Staf\n');
const flags = [];
d.candidates.forEach((c) => {
  if (c.kesehatan === 'perlu_review') flags.push(`- **${c.nama}**: catatan kesehatan perlu review manual.`);
  if (!best(c.id)) flags.push(`- **${c.nama}**: belum cocok dengan lowongan mana pun - sarankan pelatihan sertifikasi/bahasa.`);
});
L.push(flags.length ? flags.join('\n') : '- Tidak ada.');

L.push('\n## Agenda 7 Hari ke Depan\n');
L.push('| Tanggal | Kandidat | Agenda |\n|---|---|---|');
const agenda = [];
d.candidates.forEach((c) => {
  [['Wawancara', c.interview_tgl], ['Medical check-up', c.medical_tgl], ['Tenggat dokumen', c.dokumen_tenggat]].forEach(([a, dt]) => {
    if (dt) { const n = diff(d.today, dt); if (n >= 0 && n <= 7) agenda.push([dt, c.nama, a]); }
  });
});
agenda.sort().forEach(([dt, n, a]) => L.push(`| ${tgl(dt)} | ${n} | ${a} |`));

L.push('\n## Reminder Dibuat Hari Ini\n');
L.push('| Kandidat | Tahap | Trigger |\n|---|---|---|');
d.reminders.forEach((r) => L.push(`| ${r.kandidat} | ${r.tahap} | ${r.offset} |`));

return [{ json: { report: L.join('\n') + '\n', tanggal: d.today } }];
